using System;
using System.Collections.Generic;
using System.Globalization;

namespace ZenStates.Core.Hardware.Apob
{
    /// <summary>Where the name of an APCB token comes from.</summary>
    public enum ApcbTokenSource
    {
        /// <summary>CBS setup code: the token is written from this setup option (AMD CBS menu).</summary>
        Cbs,
        /// <summary>AMD Overclocking (AOD) setup code: the token is written from this setup option.</summary>
        Aod,
        /// <summary>AOD writes a value it computes from other options (encoded voltage, enable flag ...).</summary>
        AodDerived,
        /// <summary>Name from Oxide's amd-apcb crate (MPL-2.0, https://github.com/oxidecomputer/amd-apcb).</summary>
        Oxide,
    }

    /// <summary>The name, setup prompt and value labels of an APCB token.</summary>
    public sealed class ApcbTokenName
    {
        private readonly string _options;
        private Dictionary<uint, string> _labels;

        internal ApcbTokenName(string name, string prompt, string options, ApcbTokenSource source)
        {
            Name = name;
            Prompt = prompt;
            _options = options;
            Source = source;
        }

        /// <summary>Internal option name (CBS / AOD variable field name without the family suffix).</summary>
        public string Name { get; private set; }

        /// <summary>The text of the setup option, or a description for a derived value; may be empty.</summary>
        public string Prompt { get; private set; }

        public ApcbTokenSource Source { get; private set; }

        /// <summary>The setup label of <paramref name="value"/>, or null when the option has no list or the value isn't in it.</summary>
        public string GetValueLabel(uint value)
        {
            if (_options == null)
                return null;

            if (_labels == null)
            {
                var labels = new Dictionary<uint, string>();
                foreach (string item in _options.Split(';'))
                {
                    int eq = item.IndexOf('=');
                    uint v;
                    if (eq > 0 && uint.TryParse(item.Substring(0, eq), NumberStyles.Integer, CultureInfo.InvariantCulture, out v) && !labels.ContainsKey(v))
                        labels[v] = item.Substring(eq + 1);
                }
                _labels = labels;
            }

            string label;
            return _labels.TryGetValue(value, out label) ? label : null;
        }
    }

    /// <summary>
    /// Names of APCB v3 tokens (AM5 desktop, Phoenix and Strix / Krackan AGESA). Token ids are the same across these
    /// families, only the CBS variable layout differs.
    /// </summary>
    /// <remarks>
    /// Generated from MSI MAG B650 TOMAHAWK WIFI BIOS 1.A29 (E7E73AMSI.1A29): the CBS setup forms (CbsSetupDxeRPL /
    /// PHX / STX) give each option's name, prompt and value list and its offset in the AmdSetup variable; the code
    /// that writes the APCB (CbsSetupSmm*, AodSmm) gives the token id written from each offset. The AOD option names
    /// come from AodSmm's option table, the prompts from AodDxe's forms. CBS skips options left at Auto, so a token
    /// in the writable APCB (type 0x60) is an option that was set. AOD writes its tokens with priority 2, CBS with 3.
    /// Tokens that no setup option writes are named from Oxide's amd-apcb crate (MPL-2.0) where it has them.
    /// </remarks>
    public static class ApcbTokenNames
    {
        /// <summary>The name of token <paramref name="id"/>, or null when it is not known.</summary>
        public static ApcbTokenName Get(uint id)
        {
            ApcbTokenName name;
            return Names.TryGetValue(id, out name) ? name : null;
        }

        public static int Count
        {
            get { return Names.Count; }
        }

